/**
 * Pure-JavaScript SHA-1 (FIPS 180-4), written from scratch.
 *
 * This is the digest module that `pbkdf2.PBKDF2` uses by default
 * (`digestmodule=SHA1`), so it is the foundation of the whole port.
 *
 * The class keeps an explicit 5-word chaining state plus a 64-byte residual
 * buffer, which makes `clone()` cheap.  HMAC exploits that: the ipad/opad
 * key blocks are compressed exactly once and every PRF call just clones the
 * resulting state instead of re-hashing the 64-byte key block.
 */

export const BLOCK_SIZE = 64;
export const DIGEST_SIZE = 20;

const INIT_H0 = 0x67452301 | 0;
const INIT_H1 = 0xefcdab89 | 0;
const INIT_H2 = 0x98badcfe | 0;
const INIT_H3 = 0x10325476 | 0;
const INIT_H4 = 0xc3d2e1f0 | 0;

const K0 = 0x5a827999 | 0;
const K1 = 0x6ed9eba1 | 0;
const K2 = 0x8f1bbcdc | 0;
const K3 = 0xca62c1d6 | 0;

// Message schedule scratch space.  Single-threaded, so one shared array is safe
// and avoids allocating 80 words per compression.
const W = new Int32Array(80);

/**
 * Compress `count` consecutive 64-byte blocks of `buf` starting at `offset`
 * into the 5-word state `h` (an Int32Array of length 5), in place.
 */
export function compress(h, buf, offset, count) {
  let a = h[0];
  let b = h[1];
  let c = h[2];
  let d = h[3];
  let e = h[4];

  for (let blk = 0; blk < count; blk++) {
    let p = offset + blk * BLOCK_SIZE;
    for (let i = 0; i < 16; i++) {
      W[i] = (buf[p] << 24) | (buf[p + 1] << 16) | (buf[p + 2] << 8) | buf[p + 3];
      p += 4;
    }
    for (let i = 16; i < 80; i++) {
      const n = W[i - 3] ^ W[i - 8] ^ W[i - 14] ^ W[i - 16];
      W[i] = (n << 1) | (n >>> 31);
    }

    const sa = a;
    const sb = b;
    const sc = c;
    const sd = d;
    const se = e;

    for (let i = 0; i < 20; i++) {
      const t = (((a << 5) | (a >>> 27)) + ((b & c) | (~b & d)) + e + W[i] + K0) | 0;
      e = d;
      d = c;
      c = (b << 30) | (b >>> 2);
      b = a;
      a = t;
    }
    for (let i = 20; i < 40; i++) {
      const t = (((a << 5) | (a >>> 27)) + (b ^ c ^ d) + e + W[i] + K1) | 0;
      e = d;
      d = c;
      c = (b << 30) | (b >>> 2);
      b = a;
      a = t;
    }
    for (let i = 40; i < 60; i++) {
      const t = (((a << 5) | (a >>> 27)) + ((b & c) | (b & d) | (c & d)) + e + W[i] + K2) | 0;
      e = d;
      d = c;
      c = (b << 30) | (b >>> 2);
      b = a;
      a = t;
    }
    for (let i = 60; i < 80; i++) {
      const t = (((a << 5) | (a >>> 27)) + (b ^ c ^ d) + e + W[i] + K3) | 0;
      e = d;
      d = c;
      c = (b << 30) | (b >>> 2);
      b = a;
      a = t;
    }

    a = (a + sa) | 0;
    b = (b + sb) | 0;
    c = (c + sc) | 0;
    d = (d + sd) | 0;
    e = (e + se) | 0;
  }

  h[0] = a;
  h[1] = b;
  h[2] = c;
  h[3] = d;
  h[4] = e;
}

export class Sha1 {
  constructor() {
    this.h = new Int32Array(5);
    this.h[0] = INIT_H0;
    this.h[1] = INIT_H1;
    this.h[2] = INIT_H2;
    this.h[3] = INIT_H3;
    this.h[4] = INIT_H4;
    this.buf = new Uint8Array(BLOCK_SIZE);
    this.bufLen = 0;
    // Total message length in bytes.  A plain Number is exact well past any
    // input this program can be handed (2**53 bytes).
    this.total = 0;
  }

  /** Cheap snapshot copy — the reason HMAC can precompute key states. */
  clone() {
    const out = new Sha1();
    out.h.set(this.h);
    out.buf.set(this.buf);
    out.bufLen = this.bufLen;
    out.total = this.total;
    return out;
  }

  /** Restore this instance from a previously cloned/snapshotted state. */
  copyFrom(other) {
    this.h.set(other.h);
    this.buf.set(other.buf);
    this.bufLen = other.bufLen;
    this.total = other.total;
    return this;
  }

  update(bytes) {
    const len = bytes.length;
    this.total += len;

    let i = 0;
    if (this.bufLen > 0) {
      const need = BLOCK_SIZE - this.bufLen;
      if (len < need) {
        this.buf.set(bytes, this.bufLen);
        this.bufLen += len;
        return this;
      }
      this.buf.set(bytes.subarray(0, need), this.bufLen);
      compress(this.h, this.buf, 0, 1);
      this.bufLen = 0;
      i = need;
    }

    const whole = (len - i) >>> 6;
    if (whole > 0) {
      compress(this.h, bytes, i, whole);
      i += whole << 6;
    }

    if (i < len) {
      this.buf.set(bytes.subarray(i), 0);
      this.bufLen = len - i;
    }
    return this;
  }

  /**
   * Finalise into `out` (a 20-byte view) or into a fresh Uint8Array.
   * The instance must not be updated afterwards.
   */
  digest(out) {
    const dst = out || new Uint8Array(DIGEST_SIZE);
    const bitLenHi = Math.floor(this.total / 0x20000000) | 0;
    const bitLenLo = (this.total * 8) | 0;

    const pad = this.buf;
    let n = this.bufLen;
    pad[n++] = 0x80;
    if (n > BLOCK_SIZE - 8) {
      pad.fill(0, n, BLOCK_SIZE);
      compress(this.h, pad, 0, 1);
      n = 0;
    }
    pad.fill(0, n, BLOCK_SIZE - 8);
    pad[BLOCK_SIZE - 8] = (bitLenHi >>> 24) & 0xff;
    pad[BLOCK_SIZE - 7] = (bitLenHi >>> 16) & 0xff;
    pad[BLOCK_SIZE - 6] = (bitLenHi >>> 8) & 0xff;
    pad[BLOCK_SIZE - 5] = bitLenHi & 0xff;
    pad[BLOCK_SIZE - 4] = (bitLenLo >>> 24) & 0xff;
    pad[BLOCK_SIZE - 3] = (bitLenLo >>> 16) & 0xff;
    pad[BLOCK_SIZE - 2] = (bitLenLo >>> 8) & 0xff;
    pad[BLOCK_SIZE - 1] = bitLenLo & 0xff;
    compress(this.h, pad, 0, 1);

    const h = this.h;
    for (let i = 0; i < 5; i++) {
      const v = h[i];
      const o = i << 2;
      dst[o] = (v >>> 24) & 0xff;
      dst[o + 1] = (v >>> 16) & 0xff;
      dst[o + 2] = (v >>> 8) & 0xff;
      dst[o + 3] = v & 0xff;
    }
    return dst;
  }
}

export function sha1(bytes) {
  return new Sha1().update(bytes).digest();
}

/** Descriptor consumed by `hmac.mjs`, mirroring a Python hash module. */
export const SHA1 = Object.freeze({
  name: 'sha1',
  blockSize: BLOCK_SIZE,
  digestSize: DIGEST_SIZE,
  create: () => new Sha1(),
});

