/**
 * HMAC (RFC 2104) over any hash descriptor exported by a digest module.
 *
 * `pbkdf2.PBKDF2` builds its default PRF as
 *     lambda p, s: HMAC(p, s, SHA1).digest()
 * so this module only needs the "one-shot digest" shape.
 *
 * `HmacKey` precomputes the compressed ipad/opad states once per key.  PBKDF2
 * calls the PRF `iterations` times with the *same* passphrase, so this turns
 * each iteration into exactly two SHA-1 compressions.
 */

const IPAD = 0x36;
const OPAD = 0x5c;

export class HmacKey {
  /**
   * @param {Uint8Array} key
   * @param {{blockSize:number, digestSize:number, create:() => object}} hash
   */
  constructor(key, hash) {
    this.hash = hash;
    this.digestSize = hash.digestSize;

    const blockSize = hash.blockSize;
    // Keys longer than one block are replaced by their digest; shorter keys are
    // right-padded with zeros.
    let k = key;
    if (k.length > blockSize) {
      k = hash.create().update(k).digest();
    }

    const inner = new Uint8Array(blockSize);
    const outer = new Uint8Array(blockSize);
    inner.fill(IPAD);
    outer.fill(OPAD);
    for (let i = 0; i < k.length; i++) {
      inner[i] ^= k[i];
      outer[i] ^= k[i];
    }

    this.innerSeed = hash.create().update(inner);
    this.outerSeed = hash.create().update(outer);

    // Reusable working instances, refreshed from the seeds on every call.
    this._inner = this.innerSeed.clone();
    this._outer = this.outerSeed.clone();
    this._scratch = new Uint8Array(this.digestSize);

    inner.fill(0);
    outer.fill(0);
  }

  /**
   * @param {Uint8Array} message
   * @param {Uint8Array} [out] destination for the digest (length digestSize)
   * @returns {Uint8Array}
   */
  digest(message, out) {
    const inner = this._inner.copyFrom(this.innerSeed);
    inner.update(message);
    inner.digest(this._scratch);

    const outer = this._outer.copyFrom(this.outerSeed);
    outer.update(this._scratch);
    return outer.digest(out || new Uint8Array(this.digestSize));
  }
}

/** One-shot convenience wrapper: HMAC(key, message). */
export function hmac(key, message, hash) {
  return new HmacKey(key, hash).digest(message);
}

