/**
 * Python-compatible helpers for text <-> bytes and value formatting.
 */

const utf8Encoder = new TextEncoder();

/**
 * Encode a JS string the way Python encodes `str` to UTF-8.
 *
 * `pbkdf2.PBKDF2._setup` does `passphrase.encode("UTF-8")` / `salt.encode("UTF-8")`,
 * which is exactly what TextEncoder produces (lone surrogates become U+FFFD in
 * JS; Python would raise, but argv can never contain lone surrogates here).
 */
export function encodeUtf8(str) {
  return utf8Encoder.encode(str);
}

/** Lowercase hex, matching `bytes.hex()`. */
export function toHex(bytes) {
  let out = '';
  for (let i = 0; i < bytes.length; i++) {
    out += HEX[bytes[i]];
  }
  return out;
}

const HEX = [];
for (let i = 0; i < 256; i++) {
  HEX.push(i.toString(16).padStart(2, '0'));
}

/**
 * Reproduce `repr()` of a Python `str`, which argparse embeds in its
 * "invalid int value: %r" diagnostics.
 *
 * Python prefers single quotes, but switches to double quotes when the string
 * contains a single quote and no double quote.
 */
export function pyRepr(str) {
  const quote = str.includes("'") && !str.includes('"') ? '"' : "'";
  let body = '';
  for (const ch of str) {
    const cp = ch.codePointAt(0);
    if (ch === '\\') body += '\\\\';
    else if (ch === quote) body += '\\' + quote;
    else if (ch === '\n') body += '\\n';
    else if (ch === '\r') body += '\\r';
    else if (ch === '\t') body += '\\t';
    else if (cp < 0x20 || cp === 0x7f) body += '\\x' + cp.toString(16).padStart(2, '0');
    else body += ch;
  }
  return quote + body + quote;
}

