toolUseResult.originalFile:
/**
 * A minimal, behaviour-matched subset of Python's `argparse.ArgumentParser`.
 *
 * Only what this program needs is implemented, but the observable details were
 * checked one by one against the reference executable:
 *
 *   --a val / --a=val            both accepted
 *   repeated --a                 last wins
 *   --h                          unambiguous long-option abbreviation of --help
 *   -h anywhere                  prints help to stdout, exits 0
 *   --a -1                       accepted (negative-number heuristic)
 *   --a -x                       "argument --a: expected one argument", exit 2
 *   missing required             "the following arguments are required: --a, --c"
 *   bad int                      "argument --c: invalid int value: 'xy'"
 *   unknown option / extra word  "unrecognized arguments: ...", exit 2
 *
 * Note the precedence confirmed by `-a abc --b s --c 10`: the required-argument
 * check fires *before* the unrecognized-arguments check.
 */

import { pyRepr } from './pytext.mjs';

const NEGATIVE_NUMBER = /^-\d+$|^-\d*\.\d+$/;

class ArgumentError extends Error {}

export class ArgumentParser {
  /** @param {{prog:string}} options */
  constructor({ prog }) {
    this.prog = prog;
    this.actions = [];
    this.addArgument(['-h', '--help'], { action: 'help', help: 'show this help message and exit' });
  }

  /**
   * @param {string[]} flags e.g. ['--a']
   * @param {{type?:(s:string)=>any, required?:boolean, action?:string, help?:string}} options
   */
  addArgument(flags, options = {}) {
    const long = flags.find((f) => f.startsWith('--')) || flags[0];
    this.actions.push({
      flags,
      dest: long.replace(/^--?/, '').replace(/-/g, '_'),
      metavar: long.replace(/^--?/, '').toUpperCase(),
      type: options.type || ((s) => s),
      required: Boolean(options.required),
      action: options.action || 'store',
      help: options.help || '',
    });
    return this;
  }

  formatUsage() {
    const parts = this.actions
      .filter((a) => a.action !== 'help')
      .map((a) => ` ${a.flags[0]} ${a.metavar}`)
      .join('');
    return `usage: ${this.prog} [-h]${parts}\n`;
  }

  formatHelp() {
    let out = this.formatUsage() + '\noptions:\n';
    const rows = this.actions.map((a) => [
      a.action === 'help' ? '-h, --help' : `${a.flags[0]} ${a.metavar}`,
      a.help,
    ]);
    // argparse aligns help text two spaces past the widest invocation column.
    const width = Math.max(...rows.map((r) => r[0].length));
    for (const [invocation, help] of rows) {
      out += help ? `  ${invocation.padEnd(width)}  ${help}\n` : `  ${invocation}\n`;
    }
    return out;
  }

  /** Print usage + message to stderr and exit(2), like argparse's `error()`. */
  error(message) {
    process.stderr.write(this.formatUsage());
    process.stderr.write(`${this.prog}: error: ${message}\n`);
    process.exit(2);
  }

  _lookup(optionString) {
    const exact = this.actions.find((a) => a.flags.includes(optionString));
    if (exact) return exact;
    if (!optionString.startsWith('--')) return null;
    // Unambiguous long-option prefix, e.g. --h -> --help.
    const matches = [];
    for (const action of this.actions) {
      for (const flag of action.flags) {
        if (flag.startsWith('--') && flag.startsWith(optionString)) {
          matches.push({ action, flag });
        }
      }
    }
    if (matches.length === 1) return matches[0].action;
    if (matches.length > 1) {
      const names = matches.map((m) => m.flag).join(', ');
      this.error(`ambiguous option: ${optionString} could match ${names}`);
    }
    return null;
  }

  /** True when the token should be read as an option rather than a value. */
  _looksLikeOption(token) {
    if (token === '' || token[0] !== '-') return false;
    if (token.length === 1) return false; // a lone "-" is a value
    if (NEGATIVE_NUMBER.test(token)) return false; // no option looks like a number
    if (token.includes(' ')) return false;
    return true;
  }

  /**
   * @param {string[]} argv tokens after the program name
   * @returns {Record<string, any>}
   */
  parseArgs(argv) {
    const values = Object.create(null);
    const seen = new Set();
    const extras = [];
    let afterSeparator = false;

    for (let i = 0; i < argv.length; i++) {
      const token = argv[i];

      if (token === '--' && !afterSeparator) {
        // argparse consumes the first "--" only when positionals need it; with
        // no positionals declared it survives as an unrecognized argument.
        afterSeparator = true;
        extras.push(token);
        continue;
      }

      if (!afterSeparator && this._looksLikeOption(token)) {
        let name = token;
        let inlineValue = null;
        const eq = token.indexOf('=');
        if (eq > -1) {
          name = token.slice(0, eq);
          inlineValue = token.slice(eq + 1);
        }

        const action = this._lookup(name);
        if (!action) {
          extras.push(token);
          continue;
        }

        if (action.action === 'help') {
          process.stdout.write(this.formatHelp());
          process.exit(0);
        }

        let raw;
        if (inlineValue !== null) {
          raw = inlineValue;
        } else {
          const next = argv[i + 1];
          if (next === undefined || this._looksLikeOption(next)) {
            this.error(`argument ${action.flags[0]}: expected one argument`);
          }
          raw = next;
          i += 1;
        }

        try {
          values[action.dest] = action.type(raw);
        } catch (err) {
          // argparse only converts TypeError/ValueError from the type callable
          // into a usage error; anything else is a genuine bug.
          if (!(err instanceof PyError)) throw err;
          const typeName = action.type.typeName || 'value';
          this.error(
            `argument ${action.flags[0]}: invalid ${typeName} value: ${pyRepr(raw)}`,
          );
        }
        seen.add(action.dest);
        continue;
      }

      extras.push(token);
    }

    const missing = this.actions
      .filter((a) => a.required && !seen.has(a.dest))
      .map((a) => a.flags[0]);
    if (missing.length > 0) {
      this.error(`the following arguments are required: ${missing.join(', ')}`);
    }

    if (extras.length > 0) {
      this.error(`unrecognized arguments: ${extras.join(' ')}`);
    }

    return values;
  }
}

