/**
 * Python's `int(str)` conversion, which is what argparse's `type=int` calls.
 *
 * The accepted grammar is wider than JS `Number()`:
 *   - surrounding Unicode whitespace is ignored          ->  int(" 10 ") == 10
 *   - a leading '+' is allowed                           ->  int("+10") == 10
 *   - single underscores may separate digits             ->  int("1_0") == 10
 *   - any Unicode decimal digit counts                   ->  int("١٠") == 10
 * and narrower in other ways: "1.5" and "10_" are errors.
 *
 * All four behaviours above were confirmed against the reference executable.
 */

import { PyValueError } from './pyexceptions.mjs';

/** Code points for which Python's `str.isspace()` is true. */
const SPACE_RANGES = [
  [0x09, 0x0d], [0x1c, 0x1f], [0x20, 0x20], [0x85, 0x85], [0xa0, 0xa0],
  [0x1680, 0x1680], [0x2000, 0x200a], [0x2028, 0x2029], [0x202f, 0x202f],
  [0x205f, 0x205f], [0x3000, 0x3000],
];

function isPySpace(cp) {
  for (let i = 0; i < SPACE_RANGES.length; i++) {
    if (cp >= SPACE_RANGES[i][0] && cp <= SPACE_RANGES[i][1]) return true;
  }
  return false;
}

const ND = /\p{Nd}/u;

/**
 * Decimal value of a Unicode decimal digit, or -1 if it is not one.
 *
 * Every Nd block is ten consecutive code points starting at that block's zero,
 * and the code point below a block's zero is never itself Nd — so walking down
 * to the first non-Nd neighbour yields the digit's value.
 */
function decimalValue(cp) {
  if (cp >= 0x30 && cp <= 0x39) return cp - 0x30;
  if (!ND.test(String.fromCodePoint(cp))) return -1;
  for (let d = 1; d <= 9; d++) {
    if (!ND.test(String.fromCodePoint(cp - d))) return d;
  }
  return -1;
}

/**
 * @param {string} text
 * @returns {number|bigint} a Number when exactly representable, else a BigInt
 * @throws {PyValueError} mirroring Python's `invalid literal for int()`
 */
export function pyInt(text) {
  const chars = Array.from(text);
  let i = 0;
  let j = chars.length;
  while (i < j && isPySpace(chars[i].codePointAt(0))) i++;
  while (j > i && isPySpace(chars[j - 1].codePointAt(0))) j--;

  const fail = () => {
    throw new PyValueError(`invalid literal for int() with base 10: ${text}`);
  };

  let negative = false;
  if (i < j && (chars[i] === '+' || chars[i] === '-')) {
    negative = chars[i] === '-';
    i++;
  }
  if (i >= j) fail();

  let digits = '';
  let prevWasDigit = false;
  for (; i < j; i++) {
    const ch = chars[i];
    if (ch === '_') {
      // Legal only between two digits.
      if (!prevWasDigit) fail();
      prevWasDigit = false;
      continue;
    }
    const v = decimalValue(ch.codePointAt(0));
    if (v < 0) fail();
    digits += String(v);
    prevWasDigit = true;
  }
  if (!prevWasDigit) fail(); // empty, or a trailing underscore

  const big = negative ? -BigInt(digits) : BigInt(digits);
  const asNumber = Number(big);
  return Number.isSafeInteger(asNumber) ? asNumber : big;
}

