/**
 * Python exception shapes, so the ported code can fail the same way the
 * original does (message text, exception class name, exit status).
 */

import { readFileSync } from 'node:fs';

export class PyError extends Error {
  /** @param {string} message */
  constructor(message) {
    super(message);
    this.pyMessage = message;
  }

  /** Name used on the last line of a traceback. */
  get pyName() {
    return 'Exception';
  }
}

export class PyValueError extends PyError {
  get pyName() {
    return 'ValueError';
  }
}

export class PyTypeError extends PyError {
  get pyName() {
    return 'TypeError';
  }
}

/**
 * Render an unhandled exception the way CPython does on stderr, given the
 * traceback frames the original interpreter would have shown.
 *
 * @param {PyError} error
 * @param {Array<{file:string, line:number, name:string, source?:string, caret?:string}>} frames
 */
export function formatTraceback(error, frames) {
  const lines = ['Traceback (most recent call last):'];
  for (const frame of frames) {
    lines.push(`  File "${frame.file}", line ${frame.line}, in ${frame.name}`);
    if (frame.source) lines.push(`    ${frame.source}`);
    if (frame.caret) lines.push(`             ${frame.caret}`);
  }
  lines.push(`${error.pyName}: ${error.pyMessage}`);
  return lines.join('\n') + '\n';
}

