#!/usr/bin/env node
/**
 * Node.js port of /workspace/dataset/pbkdf2/test2.py
 *
 *   parser.add_argument('--a', type=str, required=True)  # passphrase
 *   parser.add_argument('--b', type=str, required=True)  # salt
 *   parser.add_argument('--c', type=int, required=True)  # iterations
 *   result = pbkdf2.PBKDF2(args.a, args.b, iterations=args.c).read(20)
 *   print(result.hex())
 *
 * Usage: node test2.mjs --a <passphrase> --b <salt> --c <iterations>
 */

import { ArgumentParser } from './lib/argparse.mjs';
import { pyInt } from './lib/pyint.mjs';
import { PBKDF2 } from './lib/pbkdf2.mjs';
import { toHex } from './lib/pytext.mjs';
import { PyError, formatTraceback } from './lib/pyexceptions.mjs';

// argparse derives `prog` from sys.argv[0]; the reference build reports the
// frozen executable's name, so usage/error text matches it byte for byte.
const PROG = 'test2_executable';

const str = (value) => value;
str.typeName = 'str';

const int = (value) => pyInt(value);
int.typeName = 'int';

const parser = new ArgumentParser({ prog: PROG });
parser.addArgument(['--a'], { type: str, required: true }); // passphrase
parser.addArgument(['--b'], { type: str, required: true }); // salt
parser.addArgument(['--c'], { type: int, required: true }); // iterations
const args = parser.parseArgs(process.argv.slice(2));

try {
  // 使用指定迭代次数的 PBKDF2
  const result = new PBKDF2(args.a, args.b, { iterations: args.c }).read(20); // 派生 20 字节密钥
  process.stdout.write(toHex(result) + '\n');
} catch (err) {
  if (!(err instanceof PyError)) throw err;
  // Reproduce the frozen interpreter's unhandled-exception report and status.
  process.stderr.write(
    formatTraceback(err, [
      {
        file: 'test2.py',
        line: 12,
        name: '<module>',
        source:
          'result = pbkdf2.PBKDF2(args.a, args.b, iterations=args.c).read(20)  # 派生 20 字节密钥',
        caret: '^'.repeat(49),
      },
      { file: 'pbkdf2.py', line: 141, name: '__init__' },
      { file: 'pbkdf2.py', line: 205, name: '_setup' },
    ]),
  );
  process.stderr.write(
    `[PYI-${process.pid}:ERROR] Failed to execute script 'test2' due to unhandled exception!\n`,
  );
  process.exit(1);
}

