// Generate random (passphrase, salt, iterations) triples, exercising ASCII,
// unicode, empty strings, and salt lengths that straddle SHA-1 block edges.
import { randomInt } from 'node:crypto';
const POOLS = [
  "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789",
  "!@#$%^&*()_+-=[]{}|;:,.<>?/~`'\"\\ ",
  "äöüßéèêñçÅØæ",
  "中文日本語한국어",
  "😀🔑🧂🚀",
];
function rnd(maxLen) {
  const n = randomInt(0, maxLen + 1);
  let s = '';
  for (let i = 0; i < n; i++) {
    const p = POOLS[randomInt(0, POOLS.length)];
    s += Array.from(p)[randomInt(0, Array.from(p).length)];
  }
  return s;
}
const cases = [];
for (let i = 0; i < 120; i++) {
  cases.push([rnd(24), rnd(80), String(randomInt(1, 3000))]);
}
// Deliberate edge shapes: empty, exactly 64-byte salt (HMAC block size),
// 65-byte salt (forces key/message spillover), long passphrase > block size.
cases.push(['', '', '1']);
cases.push(['', 'salt', '1']);
cases.push(['pass', '', '1']);
cases.push(['x'.repeat(63), 'y'.repeat(63), '3']);
cases.push(['x'.repeat(64), 'y'.repeat(64), '3']);
cases.push(['x'.repeat(65), 'y'.repeat(65), '3']);
cases.push(['x'.repeat(200), 'y'.repeat(200), '2']);
cases.push(['pässwörd☃', 'sält☃', '100']);
cases.push(['\t\n\r', ' \t ', '7']);
console.log(JSON.stringify(cases));
EOF
