check('"abc"',   toHex(sha1(enc('abc'))), 'a9993e364706816aba3e25717850c26c9cd0d89d');
check('448-bit', toHex(sha1(enc('abcdbcdecdefdefgefghfghighijhijkijkljklmklmnlmnomnopnopq'))),
