check('1M "a"',  toHex(sha1(enc('a'.repeat(1000000)))), '34aa973cd4c4daa4f61eeb2bdbad27316534016f');

console.log('HMAC-SHA-1 (RFC 2202):');
check('rfc2202-1', toHex(hmac(new Uint8Array(20).fill(0x0b), enc('Hi There'), SHA1)),
