                   'aa4ae5e15272d00e95705637ce8a3b55ed402112');

console.log('PBKDF2-HMAC-SHA1 (RFC 6070):');
check('c=1  dkLen=20',  toHex(pbkdf2('password', 'salt', 1, 20)),    '0c60c80f961f0e71f3a9b524af6012062fe037a6');
check('c=2  dkLen=20',  toHex(pbkdf2('password', 'salt', 2, 20)),    'ea6c014dc72d6f8ccd1ed92ace1d41f0d8de8957');
check('c=4096 dkLen=20',toHex(pbkdf2('password', 'salt', 4096, 20)), '4b007901b765489abead49d926f721d065a429c1');
// dkLen=25 spans two SHA-1 blocks: exercises F(2) and the read() concat path.
check('c=4096 dkLen=25', toHex(pbkdf2('passwordPASSWORDpassword',
      'saltSALTsaltSALTsaltSALTsaltSALTsalt', 4096, 25)),
      '3d2eec4fe41c849b80c8d83662c0e44a8b291a964cf2f07038');
// Embedded NULs, dkLen=16: exercises the partial-block remainder.
check('NUL dkLen=16', toHex(pbkdf2(enc('pass\0word'), enc('sa\0lt'), 4096, 16)),
      '56fa6aa75548099dcc37d7f03425e0c3');

console.log('read() stream semantics (buffered remainder):');
const oneShot = toHex(pbkdf2('password', 'salt', 100, 60));
const s = new PBKDF2('password', 'salt', { iterations: 100 });
const pieces = toHex(s.read(3)) + toHex(s.read(17)) + toHex(s.read(1)) + toHex(s.read(39));
check('3+17+1+39 == 60', pieces, oneShot);
const s2 = new PBKDF2('password', 'salt', { iterations: 100 });
check('hexread(20)', s2.hexread(20), oneShot.slice(0, 40));

console.log(fail === 0 ? '\nALL VECTORS PASS' : `\n${fail} FAILURES`);
process.exit(fail === 0 ? 0 : 1);
EOF
