/**
 * Python exception shapes, so the ported code can fail the same way the
 * original does (message text, exception class name, exit status).
 */

import { readFileSync } from 'node:fs';

export class PyError extends Error {
  /** @param {string} message */
  constructor(message) {
    super(message);
    this.pyMessage = message;
  }

  /** Name used on the last line of a traceback. */
  get pyName() {
    return 'Exception';
  }
}

export class PyValueError extends PyError {
  get pyName() {
    return 'ValueError';
  }
}

export class PyTypeError extends PyError {
  get pyName() {
    return 'TypeError';
  }
}

/**
 * CPython's `linecache`: fetch a 1-based line from a source file, resolved
 * relative to the current working directory, or null when unreadable.
 *
 * This is why the reference executable's traceback shows the offending source
 * line when it is run from the directory containing `test2.py`, and omits it
 * everywhere else — the frozen bundle carries no sources, so the interpreter
 * only ever finds the file by chance.
 */
function linecache(file, line) {
  try {
    const text = readFileSync(file, 'utf8');
    const lines = text.split('\n');
    const raw = lines[line - 1];
    return raw === undefined ? null : raw;
  } catch {
    return null;
  }
}

/**
 * Render an unhandled exception the way CPython does on stderr, given the
 * traceback frames the original interpreter would have shown.
 *
 * @param {PyError} error
 * @param {Array<{file:string, line:number, name:string,
 *                caret?:{start:number, length:number}}>} frames
 */
export function formatTraceback(error, frames) {
  const lines = ['Traceback (most recent call last):'];
  for (const frame of frames) {
    lines.push(`  File "${frame.file}", line ${frame.line}, in ${frame.name}`);

    const source = linecache(frame.file, frame.line);
    if (source === null) continue;
    const stripped = source.trim();
    if (stripped === '') continue;
    lines.push(`    ${stripped}`);

    // CPython 3.11+ underlines the sub-expression that raised. Its column
    // offsets are relative to the stripped line.
    if (frame.caret) {
      lines.push(`    ${' '.repeat(frame.caret.start)}${'^'.repeat(frame.caret.length)}`);
    }
  }
  lines.push(`${error.pyName}: ${error.pyMessage}`);
  return lines.join('\n') + '\n';
}

