1	/**
2	 * Port of the `pbkdf2` PyPI module's `PBKDF2` class (PKCS#5 v2.0 / RFC 2898).
3	 *
4	 * The class is a *file-like key stream*, not a one-shot function: `read(n)`
5	 * pulls n bytes out of the concatenation F(1) || F(2) || ... and keeps the
6	 * unread remainder buffered for the next call.  That is reproduced here
7	 * faithfully, because `read(20)` with the default SHA-1 digest happens to land
8	 * exactly on a block boundary but callers of this module need not.
9	 *
10	 *     F(i) = U1 ^ U2 ^ ... ^ Uc
11	 *     U1   = PRF(passphrase, salt || INT_BE32(i))
12	 *     Uj   = PRF(passphrase, U(j-1))
13	 *
14	 * Sanity checks and their messages match the original `_setup`, verified
15	 * against the reference executable (iterations=0 and iterations=-1 both raise
16	 * `ValueError: iterations must be at least 1`).
17	 */
18	
19	import { SHA1 } from './sha1.mjs';
20	import { HmacKey } from './hmac.mjs';
21	import { encodeUtf8, toHex } from './pytext.mjs';
22	import { PyTypeError, PyValueError } from './pyexceptions.mjs';
23	
24	const MAX_BLOCKS = 0xffffffff;
25	
26	/** Build the default PRF: `lambda p, s: HMAC(p, s, digestmodule).digest()`. */
27	function makeHmacPrf(passphrase, digestmodule) {
28	  const key = new HmacKey(passphrase, digestmodule);
29	  return {
30	    digestSize: key.digestSize,
31	    call: (message, out) => key.digest(message, out),
32	  };
33	}
34	
35	export class PBKDF2 {
36	  /**
37	   * @param {string|Uint8Array} passphrase
38	   * @param {string|Uint8Array} salt
39	   * @param {{iterations?:number|bigint, digestmodule?:object}} [options]
40	   */
41	  constructor(passphrase, salt, options = {}) {
42	    const { iterations = 1000, digestmodule = SHA1 } = options;
43	    this.closed = false;
44	    this._setup(passphrase, salt, iterations, digestmodule);
45	  }
46	
47	  _setup(passphrase, salt, iterations, digestmodule) {
48	    // passphrase and salt must be text or bytes; text is encoded as UTF-8.
49	    const passBytes = toBytes(passphrase, 'passphrase');
50	    const saltBytes = toBytes(salt, 'salt');
51	
52	    // iterations must be an integer >= 1.
53	    if (typeof iterations === 'bigint') {
54	      // A BigInt is always integral.
55	    } else if (typeof iterations !== 'number' || !Number.isInteger(iterations)) {
56	      throw new PyTypeError('iterations must be an integer');
57	    }
58	    if (iterations < 1) {
59	      throw new PyValueError('iterations must be at least 1');
60	    }
61	
62	    this._passphrase = passBytes;
63	    this._salt = saltBytes;
64	    this._iterations = iterations;
65	    this._prf = makeHmacPrf(passBytes, digestmodule);
66	
67	    this._buf = new Uint8Array(0);
68	    this._blockNum = 0;
69	
70	    // salt || INT_BE32(i), rebuilt in place for each block.
71	    this._saltBlock = new Uint8Array(saltBytes.length + 4);
72	    this._saltBlock.set(saltBytes, 0);
73	  }
74	
75	  /** Read `count` bytes from the key stream. */
76	  read(count) {
77	    if (this.closed) {
78	      throw new PyValueError('file-like object is closed');
79	    }
80	
81	    const blockSize = this._prf.digestSize;
82	    let size = this._buf.length;
83	    const blocks = [this._buf];
84	    let i = this._blockNum;
85	    while (size < count) {
86	      i += 1;
87	      blocks.push(this._f(i));
88	      size += blockSize;
89	    }
90	
91	    const joined = concat(blocks, size);
92	    this._buf = joined.slice(count);
93	    this._blockNum = i;
94	    return joined.slice(0, count);
95	  }
96	
97	  /** `read(count).hex()`, matching the module's `hexread`. */
98	  hexread(count) {
99	    return toHex(this.read(count));
100	  }
101	
102	  close() {
103	    if (!this.closed) {
104	      this._passphrase = null;
105	      this._salt = null;
106	      this._buf = new Uint8Array(0);
107	      this._prf = null;
108	      this.closed = true;
109	    }
110	  }
111	
112	  /** F(i) = U1 ^ U2 ^ ... ^ U_iterations */
113	  _f(i) {
114	    if (!(i >= 1 && i <= MAX_BLOCKS)) {
115	      throw new PyValueError('block number out of range');
116	    }
117	
118	    const block = this._saltBlock;
119	    const base = block.length - 4;
120	    block[base] = (i >>> 24) & 0xff;
121	    block[base + 1] = (i >>> 16) & 0xff;
122	    block[base + 2] = (i >>> 8) & 0xff;
123	    block[base + 3] = i & 0xff;
124	
125	    const prf = this._prf;
126	    const size = prf.digestSize;
127	    const result = new Uint8Array(size);
128	
129	    // Two scratch buffers alternate as PRF output, so the iteration loop
130	    // allocates nothing.
131	    const bufA = new Uint8Array(size);
132	    const bufB = new Uint8Array(size);
133	
134	    let u = prf.call(block, bufA);
135	    result.set(u);
136	
137	    const total = Number(this._iterations);
138	    for (let j = 2; j <= total; j++) {
139	      u = prf.call(u, u === bufA ? bufB : bufA);
140	      for (let k = 0; k < size; k++) result[k] ^= u[k];
141	    }
142	    return result;
143	  }
144	}
