152	function concat(chunks, total) {
153	  if (chunks.length === 1) return chunks[0];
154	  const out = new Uint8Array(total);
155	  let offset = 0;
156	  for (const chunk of chunks) {
157	    out.set(chunk, offset);
158	    offset += chunk.length;
159	  }
