/**
 * Port of the `pbkdf2` PyPI module's `PBKDF2` class (PKCS#5 v2.0 / RFC 2898).
 *
 * The class is a *file-like key stream*, not a one-shot function: `read(n)`
 * pulls n bytes out of the concatenation F(1) || F(2) || ... and keeps the
 * unread remainder buffered for the next call.  That is reproduced here
 * faithfully, because `read(20)` with the default SHA-1 digest happens to land
 * exactly on a block boundary but callers of this module need not.
 *
 *     F(i) = U1 ^ U2 ^ ... ^ Uc
 *     U1   = PRF(passphrase, salt || INT_BE32(i))
 *     Uj   = PRF(passphrase, U(j-1))
 *
 * Sanity checks and their messages match the original `_setup`, verified
 * against the reference executable (iterations=0 and iterations=-1 both raise
 * `ValueError: iterations must be at least 1`).
 */

import { SHA1 } from './sha1.mjs';
import { HmacKey } from './hmac.mjs';
import { encodeUtf8, toHex } from './pytext.mjs';
import { PyTypeError, PyValueError } from './pyexceptions.mjs';

const MAX_BLOCKS = 0xffffffff;

/** Build the default PRF: `lambda p, s: HMAC(p, s, digestmodule).digest()`. */
function makeHmacPrf(passphrase, digestmodule) {
  const key = new HmacKey(passphrase, digestmodule);
  return {
    digestSize: key.digestSize,
    call: (message, out) => key.digest(message, out),
  };
}

export class PBKDF2 {
  /**
   * @param {string|Uint8Array} passphrase
   * @param {string|Uint8Array} salt
   * @param {{iterations?:number|bigint, digestmodule?:object}} [options]
   */
  constructor(passphrase, salt, options = {}) {
    const { iterations = 1000, digestmodule = SHA1 } = options;
    this.closed = false;
    this._setup(passphrase, salt, iterations, digestmodule);
  }

  _setup(passphrase, salt, iterations, digestmodule) {
    // passphrase and salt must be text or bytes; text is encoded as UTF-8.
    const passBytes = toBytes(passphrase, 'passphrase');
    const saltBytes = toBytes(salt, 'salt');

    // iterations must be an integer >= 1.
    if (typeof iterations === 'bigint') {
      // A BigInt is always integral.
    } else if (typeof iterations !== 'number' || !Number.isInteger(iterations)) {
      throw new PyTypeError('iterations must be an integer');
    }
    if (iterations < 1) {
      throw new PyValueError('iterations must be at least 1');
    }

    this._passphrase = passBytes;
    this._salt = saltBytes;
    this._iterations = iterations;
    this._prf = makeHmacPrf(passBytes, digestmodule);

    this._buf = new Uint8Array(0);
    this._blockNum = 0;

    // salt || INT_BE32(i), rebuilt in place for each block.
    this._saltBlock = new Uint8Array(saltBytes.length + 4);
    this._saltBlock.set(saltBytes, 0);
  }

  /** Read `count` bytes from the key stream. */
  read(count) {
    if (this.closed) {
      throw new PyValueError('file-like object is closed');
    }

    const blockSize = this._prf.digestSize;
    let size = this._buf.length;
    const blocks = [this._buf];
    let i = this._blockNum;
    while (size < count) {
      i += 1;
      blocks.push(this._f(i));
      size += blockSize;
    }

    const joined = concat(blocks, size);
    this._buf = joined.slice(count);
    this._blockNum = i;
    return joined.slice(0, count);
  }

  /** `read(count).hex()`, matching the module's `hexread`. */
  hexread(count) {
    return toHex(this.read(count));
  }

  close() {
    if (!this.closed) {
      this._passphrase = null;
      this._salt = null;
      this._buf = new Uint8Array(0);
      this._prf = null;
      this.closed = true;
    }
  }

  /** F(i) = U1 ^ U2 ^ ... ^ U_iterations */
  _f(i) {
    if (!(i >= 1 && i <= MAX_BLOCKS)) {
      throw new PyValueError('block number out of range');
    }

    const block = this._saltBlock;
    const base = block.length - 4;
    block[base] = (i >>> 24) & 0xff;
    block[base + 1] = (i >>> 16) & 0xff;
    block[base + 2] = (i >>> 8) & 0xff;
    block[base + 3] = i & 0xff;

    const prf = this._prf;
    const size = prf.digestSize;
    const result = new Uint8Array(size);

    // Two scratch buffers alternate as PRF output, so the iteration loop
    // allocates nothing.
    const bufA = new Uint8Array(size);
    const bufB = new Uint8Array(size);

    let u = prf.call(block, bufA);
    result.set(u);

    const total = Number(this._iterations);
    for (let j = 2; j <= total; j++) {
      u = prf.call(u, u === bufA ? bufB : bufA);
      for (let k = 0; k < size; k++) result[k] ^= u[k];
    }
    return result;
  }
}

function toBytes(value, what) {
  if (typeof value === 'string') return encodeUtf8(value);
  if (value instanceof Uint8Array) return value;
  throw new PyTypeError(`${what} must be str or unicode`);
}

function concat(chunks, total) {
  if (chunks.length === 1) return chunks[0];
  const out = new Uint8Array(total);
  let offset = 0;
  for (const chunk of chunks) {
    out.set(chunk, offset);
    offset += chunk.length;
  }
  return out;
}

/**
 * Convenience one-shot form: `PBKDF2(passphrase, salt, iterations).read(n)`.
 */
export function pbkdf2(passphrase, salt, iterations, dkLen, digestmodule = SHA1) {
  return new PBKDF2(passphrase, salt, { iterations, digestmodule }).read(dkLen);
}

